13	+
14	+// Convert a guest VA to a host-pointer into data_region.data. Subtracts
15	+// region.base_address so the index lands at the correct offset whether the
16	+// region starts at 0x0 (Tier-1, no shared mem) or at 0x80000000 (Tier-2,
17	+// --shared-mem-base, narrowed RAM). Without this, a guest stack VA like
18	+// 0x80700000 indexes 2 GiB into the data span, which is in-bounds for the
19	+// 0x90000000-byte owned buffer but OOB for a 128 MiB shared mmap.
20	+template<typename T = uint8_t>
21	+inline T* guest_va_to_host(uint64_t va)
22	+{
23	+  const uint64_t off = va - data_region.region.base_address;
24	+  return reinterpret_cast<T*>(data_region.data.data() + off);
25	+}
