44	  constexpr uint64_t NL_RDONLY  = 0;
45	  constexpr uint64_t NL_WRONLY  = 1;
46	  constexpr uint64_t NL_RDWR    = 2;
47	  constexpr uint64_t NL_APPEND  = 0x0008;
48	  constexpr uint64_t NL_CREAT   = 0x0200;
49	  constexpr uint64_t NL_TRUNC   = 0x0400;
50	  constexpr uint64_t NL_EXCL    = 0x0800;
51	  constexpr uint64_t NL_NONBLOCK = 0x4000;
52	  constexpr uint64_t NL_NOCTTY  = 0x8000;
53	
54	  int linux_flags = 0;
55	  switch (newlib_flags & 3) {
56	    case NL_RDONLY: linux_flags |= O_RDONLY; break;
57	    case NL_WRONLY: linux_flags |= O_WRONLY; break;
58	    case NL_RDWR:   linux_flags |= O_RDWR;   break;
59	  }
60	  if (newlib_flags & NL_APPEND)   linux_flags |= O_APPEND;
61	  if (newlib_flags & NL_CREAT)    linux_flags |= O_CREAT;
62	  if (newlib_flags & NL_TRUNC)    linux_flags |= O_TRUNC;
63	  if (newlib_flags & NL_EXCL)     linux_flags |= O_EXCL;
64	  if (newlib_flags & NL_NONBLOCK) linux_flags |= O_NONBLOCK;
65	  if (newlib_flags & NL_NOCTTY)   linux_flags |= O_NOCTTY;
66	  return linux_flags;
